#!/usr/bin/env node
/**
 * Generate shared enum constants for the React frontend by parsing
 * backend/prisma/schema.prisma with a regex.
 *
 * Why regex (not @prisma/internals): keeps the script dependency-free,
 * survives Prisma minor-version DMMF schema renames, and works on Render
 * deploys without ts-node.
 *
 * Output:
 *   frontend/src/shared/enums/generated.ts  — plain `as const` object literals
 *
 * The backend imports enum values directly from `@prisma/client` and does
 * NOT need a generated file (Prisma client already exposes them at runtime).
 *
 * Run: npm run gen:enums
 */

const fs = require('fs');
const path = require('path');

const SCHEMA_PATH = path.resolve(__dirname, '..', 'prisma', 'schema.prisma');
const FRONTEND_OUT = path.resolve(
  __dirname,
  '..',
  '..',
  'frontend',
  'src',
  'shared',
  'enums',
  'generated.ts',
);

// Whitelist of enums to share with the frontend. Excludes infrastructure-only
// enums (AccessLevel) and rarely-displayed enums to keep the bundle small.
const SHARED_ENUMS = [
  'CaseStatus',
  'IncidentStatus',
  'PetitionStatus',
  'SubjectType',
  'SubjectStatus',
  'ProposalStatus',
  'GuidanceStatus',
  'ExchangeStatus',
  'DelegationStatus',
  'ConclusionStatus',
  'AccessLevel',
  'ReportTdcStatus',
  'ReportTdcType',
  'TienDoKhacPhuc',
  'LyDoKhongKhoiTo',
  'LyDoTamDinhChiVuAn',
  'KetQuaPhucHoiVuAn',
  'LyDoTamDinhChiVuViec',
  'KetQuaPhucHoiVuViec',
  'LoaiDon',
  'LoaiNguonTin',
  'NguonPhatTin',
  'PhuongThucTiepNhan',
  'CapDoToiPham',
  'NotificationType',
  // DocumentType ĐÃ chuyển sang danh mục ĐỘNG (Catalog Registry DOCUMENT_TYPE → Directory),
  // không còn là Prisma enum — bỏ khỏi whitelist (migration 20260627000001).
  'DeadlineRuleStatus',
  'CaseProvenance', // v0.37.1
  'CaseType', // v0.44 — UTDT
  'LoaiUyThac', // v0.44 — UTDT loại ủy thác
];

function parseEnums(schemaSource) {
  // Match: enum Name { value1 value2 ... }
  const enumPattern = /enum\s+(\w+)\s*\{([\s\S]*?)\}/g;
  const result = {};
  let match;
  while ((match = enumPattern.exec(schemaSource)) !== null) {
    const [, name, body] = match;
    const values = [];
    for (const rawLine of body.split('\n')) {
      // Strip line comments
      const noComment = rawLine.replace(/\/\/.*/, '').trim();
      if (!noComment) continue;
      // Skip Prisma directives (@@map, @@index, etc.)
      if (noComment.startsWith('@@')) continue;
      // Match a single identifier — Prisma enum values are bare identifiers.
      // Allow both UPPER_CASE and lowercase (lowercase used by status-style enums
      // like DeadlineRuleStatus where Vietnamese labels are mapped via status-labels.ts).
      const identMatch = noComment.match(/^([A-Za-z][A-Za-z0-9_]*)$/);
      if (identMatch) {
        values.push(identMatch[1]);
      }
    }
    if (values.length > 0) result[name] = values;
  }
  return result;
}

function renderEnumConst(name, values) {
  const entries = values.map((v) => `  ${v}: '${v}',`).join('\n');
  return `export const ${name} = {\n${entries}\n} as const;\nexport type ${name} = (typeof ${name})[keyof typeof ${name}];\n`;
}

/**
 * v0.67 PR1 I1 — parse VALID_TRANSITIONS from incidents.constants.ts source.
 *
 * Input: TS source text containing:
 *   export const VALID_TRANSITIONS: Record<string, IncidentStatus[]> = {
 *     [IncidentStatus.TIEP_NHAN]: [IncidentStatus.DANG_XAC_MINH, ...],
 *     ...
 *   };
 *
 * Output: { TIEP_NHAN: ['DANG_XAC_MINH', ...], ... }
 *
 * Returns {} when no VALID_TRANSITIONS block found.
 */
function extractValidTransitions(source) {
  const blockMatch = source.match(
    /export\s+const\s+VALID_TRANSITIONS\s*:\s*Record[^=]*=\s*{([\s\S]*?)};/,
  );
  if (!blockMatch) return {};
  const body = blockMatch[1];
  const result = {};
  // Match each entry: [IncidentStatus.<KEY>]: [ ... ],
  const entryRe = /\[\s*IncidentStatus\.([A-Z_]+)\s*\]\s*:\s*\[([\s\S]*?)\]/g;
  let m;
  while ((m = entryRe.exec(body)) !== null) {
    const key = m[1];
    const valuesText = m[2];
    const values = [];
    const valueRe = /IncidentStatus\.([A-Z_]+)/g;
    let v;
    while ((v = valueRe.exec(valuesText)) !== null) {
      values.push(v[1]);
    }
    result[key] = values;
  }
  return result;
}

/**
 * Emit TypeScript Record literal for INCIDENT_VALID_TRANSITIONS.
 */
function emitTransitionsTypeScript(map) {
  const header = [
    '// ──────────────────────────────────────────────────────────────',
    '// AUTO-GENERATED by gen:enums — DO NOT EDIT.',
    '// Source: backend/src/incidents/incidents.constants.ts',
    '// ──────────────────────────────────────────────────────────────',
    '',
  ].join('\n');
  const entries = Object.entries(map)
    .map(([key, values]) => {
      const v = values.map((s) => `'${s}'`).join(', ');
      return `  ${key}: [${v}],`;
    })
    .join('\n');
  const body = `export const INCIDENT_VALID_TRANSITIONS = {\n${entries}\n} as const;\n`;
  return header + '\n' + body;
}

const INCIDENT_CONSTANTS_PATH = path.resolve(
  __dirname,
  '..',
  'src',
  'incidents',
  'incidents.constants.ts',
);
const FRONTEND_TRANSITIONS_OUT = path.resolve(
  __dirname,
  '..',
  '..',
  'frontend',
  'src',
  'shared',
  'enums',
  'incident-transitions.generated.ts',
);

function main() {
  const schemaSource = fs.readFileSync(SCHEMA_PATH, 'utf8');
  const allEnums = parseEnums(schemaSource);

  const missing = SHARED_ENUMS.filter((n) => !(n in allEnums));
  if (missing.length > 0) {
    throw new Error(
      `Whitelisted enums missing in schema.prisma: ${missing.join(', ')}`,
    );
  }

  const header = [
    '// ──────────────────────────────────────────────────────────────',
    '// AUTO-GENERATED — DO NOT EDIT.',
    '// Source: backend/prisma/schema.prisma',
    '// Run: cd backend && npm run gen:enums',
    '// ──────────────────────────────────────────────────────────────',
    '',
  ].join('\n');

  const body = SHARED_ENUMS.map((name) => renderEnumConst(name, allEnums[name])).join('\n');

  // Force LF line endings — Windows dev + Linux CI must agree on diffs
  const output = (header + '\n' + body).replace(/\r\n/g, '\n');

  fs.mkdirSync(path.dirname(FRONTEND_OUT), { recursive: true });
  fs.writeFileSync(FRONTEND_OUT, output, { encoding: 'utf8' });

  // v0.67 PR1 I1 — emit incident-transitions.generated.ts
  const incidentSource = fs.readFileSync(INCIDENT_CONSTANTS_PATH, 'utf8');
  const transitions = extractValidTransitions(incidentSource);
  if (Object.keys(transitions).length === 0) {
    throw new Error(
      'VALID_TRANSITIONS not found in incidents.constants.ts — schema drift?',
    );
  }
  const transitionsOutput = emitTransitionsTypeScript(transitions).replace(/\r\n/g, '\n');
  fs.writeFileSync(FRONTEND_TRANSITIONS_OUT, transitionsOutput, { encoding: 'utf8' });

  console.log(
    `Generated ${SHARED_ENUMS.length} enum(s) + ${Object.keys(transitions).length} transition(s) → frontend/src/shared/enums/`,
  );
}

module.exports = {
  // Exported so `test/enums-sync.spec.ts` asserts against the same list the
  // generator actually emits. It used to keep a hand-copied mirror, which
  // drifted (DocumentType stayed behind after it became a dynamic catalog)
  // and went unnoticed because that spec was never picked up by jest.
  SHARED_ENUMS,
  // Same reason as SHARED_ENUMS: the sync spec used to keep its own copy of
  // this parser, and it diverged — the copy only accepted UPPER_CASE values,
  // so lowercase enums like DeadlineRuleStatus parsed as empty and looked
  // "missing from the schema".
  parseEnums,
  extractValidTransitions,
  emitTransitionsTypeScript,
};

if (require.main === module) {
  main();
}
